// Cost Watchdog · relevo 42 · cada fuente en SU unidad; una fuente que no responde es null («sin datos»), NUNCA 0 (un cero que parece un dato es peor que no mirar).
const filas = (nombre) => { try { return $(nombre).all().map((i) => i.json).filter((j) => j && typeof j === 'object'); } catch (e) { return []; } };
// Anthropic · el rollup diario de la base (agent_invocations_daily_rollup): una fila por agente y modelo, con total_cost_usd. HOY = suma de esas filas.
const hoyFilas = filas('Fetch Anthropic').filter((j) => j.total_cost_usd !== undefined && j.total_cost_usd !== null);
const anthropicHoy = hoyFilas.reduce((s, r) => s + (parseFloat(r.total_cost_usd) || 0), 0);
// OpenAI · el endpoint de uso puede no responder con una llave de API: si no trae el número, es null
const o = filas('Fetch OpenAI')[0] || {};
const openaiUsd = typeof o.total_usage === 'number' ? o.total_usage / 100 : null;
// Apify · gasto del ciclo (data.current.monthlyUsageUsd); si no viene, null
const a = filas('Fetch Apify')[0] || {};
const apifyRaw = a.data?.current?.monthlyUsageUsd ?? a.current?.monthlyUsageUsd;
const apifyUsd = typeof apifyRaw === 'number' ? apifyRaw : (apifyRaw !== undefined && apifyRaw !== null && !isNaN(parseFloat(apifyRaw)) ? parseFloat(apifyRaw) : null);
const sinDatos = [];
if (openaiUsd === null) sinDatos.push('OpenAI');
if (apifyUsd === null) sinDatos.push('Apify');
return [{ json: { anthropic_hoy_usd: anthropicHoy, anthropic_filas_hoy: hoyFilas.length, openai_ciclo_usd: openaiUsd, apify_ciclo_usd: apifyUsd, fuentes_sin_datos: sinDatos, timestamp: new Date().toISOString() } }];

// Cost Watchdog · relevo 42 · compara el gasto de Anthropic de HOY (rollup diario) con el promedio de los días ANTERIORES con datos (mismo rollup). Sin historial: «sin datos», no relleno.
const ag = $('Aggregate Costs').first().json;
const hoy = $now.toUTC().toFormat('yyyy-MM-dd');
const hist = (() => { try { return $('Fetch Historial').all().map((i) => i.json).filter((j) => j && j.day && j.total_cost_usd !== undefined && j.total_cost_usd !== null); } catch (e) { return []; } })();
const porDia = {};
for (const r of hist) { if (r.day === hoy) continue; porDia[r.day] = (porDia[r.day] || 0) + (parseFloat(r.total_cost_usd) || 0); }
const dias = Object.keys(porDia);
const sinHistorial = dias.length === 0;
const promedio = sinHistorial ? null : dias.reduce((s, d) => s + porDia[d], 0) / dias.length;
const actual = ag.anthropic_hoy_usd || 0;
let esAnomalia = !sinHistorial && actual > promedio * 2 && actual > 0.10;
// el rollup es una vista que se refresca: si su última actualización es vieja, el dato de hoy puede estar atrasado (se dice)
const refrescos = hist.map((r) => r.refreshed_at).filter(Boolean).sort();
const ultimo = refrescos.length ? refrescos[refrescos.length - 1] : null;
const horasDesdeRefresco = ultimo ? Math.round(((Date.now() - new Date(ultimo).getTime()) / 3600000) * 10) / 10 : null;
// no repetir: un aviso por día (en ejecuciones reales; una prueba manual no guarda este dato)
const sd = $getWorkflowStaticData('global');
let yaAvisado = false;
if (esAnomalia) { if (sd.ultimo_aviso_dia === hoy) { yaAvisado = true; esAnomalia = false; } else { sd.ultimo_aviso_dia = hoy; } }
const f = (n) => (n === null || n === undefined ? 'sin datos' : 'US$ ' + Number(n).toFixed(2));
const mensaje = '💸 *Cost Watchdog* · el gasto de Anthropic de HOY es ' + f(actual) + ', más del doble del promedio de los últimos ' + dias.length + ' día(s) con datos (' + f(promedio) + '). Fuente: rollup diario de la base' + (horasDesdeRefresco !== null ? ' (refrescado hace ' + horasDesdeRefresco + ' h)' : '') + '. OpenAI (ciclo): ' + f(ag.openai_ciclo_usd) + ' · Apify (ciclo): ' + f(ag.apify_ciclo_usd) + '.';
return [{ json: { fecha: hoy, anthropic_hoy_usd: actual, promedio_dias_anteriores_usd: promedio, dias_con_datos: dias.length, sin_historial: sinHistorial, is_anomaly: esAnomalia, aviso_ya_enviado_hoy: yaAvisado, rollup_refrescado_hace_h: horasDesdeRefresco, openai_ciclo_usd: ag.openai_ciclo_usd, apify_ciclo_usd: ag.apify_ciclo_usd, fuentes_sin_datos: ag.fuentes_sin_datos, mensaje, timestamp: ag.timestamp } }];

